import { ArrowRight, Check } from 'lucide-react'; import SectionTitle from '../components/SectionTitle';
const offerings=['International recruitment support','Talent sourcing and candidate screening','Candidate profile guidance','Employer recruitment solutions'];
export default function ServicesPage({page,navigate}){const employers=page==='employers';return <><section className="page-hero"><div className="container"><p className="eyebrow light">{employers?'For employers':'Our services'}</p><h1>{employers?'Recruitment support\nthat moves with you.':'Thoughtful recruitment,\nclearer outcomes.'}</h1><p>{employers?'Build the team your organisation needs with a professional, people-first recruitment partner.':'Whether you are looking for talent or a new path, our support is designed around your next move.'}</p></div></section><section className="section"><div className="container"><div className="row g-5 align-items-center"><div className="col-12 col-lg-6"><SectionTitle centered={false} eyebrow="What we offer" title={employers?'Find the people who can help your organisation grow.':'A focused service for every stage of your journey.'} text="We make space for the conversations, details and direction that help recruitment decisions feel more confident."/><ul className="check-list">{offerings.map(x=><li key={x}><Check/>{x}</li>)}</ul><button className="btn btn-primary" onClick={()=>navigate('contact')}>{employers?'Partner with us':'Contact our team'} <ArrowRight/></button></div><div className="col-12 col-lg-6"><div className="service-panel"><span>AMREEN CONSULTANCY</span><h2>Right people.<br/><em>Better futures.</em></h2><p>Professional support for global talent connections.</p></div></div></div></div></section></>}
